    function averageColor(data) {
      let r = 0;
      let g = 0;
      let b = 0;
      let a = 0;
      const count = data.length / 4;
      for (let i = 0; i < data.length; i += 4) {
        r += data[i];
        g += data[i + 1];
        b += data[i + 2];
        a += data[i + 3];
      }
      return {
        r: Math.round(r / count),
        g: Math.round(g / count),
        b: Math.round(b / count),
        a: Math.round(a / count)
      };
    }

    function toHex({ r, g, b }) {
      return `#${[r, g, b].map((value) => value.toString(16).padStart(2, "0")).join("")}`;
    }

    function isBackground({ r, g, b, a }) {
      return a < 16 || (r > 244 && g > 244 && b > 244);
    }

    async function sampleUploadedImage() {
      const file = fileInput.files[0];
      if (!file) return;

      const bitmap = await createImageBitmap(file);
      const ctx = sourceCanvas.getContext("2d", { willReadFrequently: true });
      sourceCanvas.width = bitmap.width;
      sourceCanvas.height = bitmap.height;
      ctx.clearRect(0, 0, sourceCanvas.width, sourceCanvas.height);
      ctx.drawImage(bitmap, 0, 0);

      const cellW = bitmap.width / gridSize;
      const cellH = bitmap.height / gridSize;
      const sampled = emptyMatrix();

      for (let y = 0; y < gridSize; y += 1) {
        for (let x = 0; x < gridSize; x += 1) {
          const sx = Math.floor(x * cellW);
          const sy = Math.floor(y * cellH);
          const sw = Math.max(1, Math.floor((x + 1) * cellW) - sx);
          const sh = Math.max(1, Math.floor((y + 1) * cellH) - sy);
          const color = averageColor(ctx.getImageData(sx, sy, sw, sh).data);
          sampled[y][x] = isBackground(color) ? "" : toHex(color);
        }
      }

      currentMatrix = sampled;
      renderMatrix(currentMatrix);
    }

    sampleButton.addEventListener("click", sampleUploadedImage);
    renderSwatches();
    renderMatrix(currentMatrix);
